// Builds / verifies test/fixtures/spike-pure/spike-pure.cjs: a VERBATIM copy of the pure functions of the SPK-07 spike at
// freeze B (harness sha256 c46e72077cae491c919254b961571842919b4bb80b3dcad963b141b34f8b6388), so no test depends on the
// untracked spike directory. Only the leading `export ` keyword of each top-level declaration is removed and a
// module.exports line is appended; every function and constant text is otherwise byte-for-byte the spike's.
//
//   node test/fixtures/spike-pure/verify-copy.mjs          verify the committed copy against the spike (needs the spike)
//   node test/fixtures/spike-pure/verify-copy.mjs --write  regenerate the committed copy from the spike
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..', '..');
const grounding = join(root, 'evaluation', 'grounding');
const FREEZE_B_HARNESS_SHA256 = 'c46e72077cae491c919254b961571842919b4bb80b3dcad963b141b34f8b6388';

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');

const SOURCES = [
  {
    file: join(grounding, 'lib', 'perceive.mjs'), key: 'lib/perceive.mjs',
    names: ['MAX_LINE_CHARS', 'OUTLINE_BYTES', 'OPTION_CAP', 'PUNCT', 'norm', 'words', 'FOCUS_STOPWORDS', 'STOP', 'bound', 'quote', 'createMatcher', 'safeUrl',
      'INTERACTIVE_ROLES', 'VALUE_ROLES', 'LANDMARK_ROLES', 'FORM_CONTROL_ROLES', 'TRANSPARENT_ROLES', 'LABEL_ROLES', 'GROUP_ROLES', 'HINT_ROLES', 'NAME_OMIT_ROLES',
      'countKind', 'buildRendered', 'annotate', 'showRef', 'renderLine', 'utf8', 'project', 'evidenceFor'],
  },
  { file: join(grounding, 'lib', 'arms', 'S3.mjs'), key: 'lib/arms/S3.mjs', names: ['intentGate', 'SELECT_TARGETS', 'CHECK_TARGETS', 'operationTargetGate', 'actionGate'] },
  {
    file: join(here, 'regate-gates.mjs'), key: 'test/fixtures/spike-pure/regate-gates.mjs',
    names: ['QUOTED', 'LINE', 'MORE_OPTIONS', 'MORE_NODES', 'parseOutline', 'subtree', 'trim', 'g1', 'collapse', 'g2'],
  },
];

/** The text of the top-level declaration `name` (with the comment block attached above it), `export ` removed. */
function declaration(lines, name) {
  const isStart = (line) => new RegExp(`^(export )?(function|const) ${name}\\b`, 'u').test(line);
  const at = lines.findIndex(isStart);
  if (at < 0) throw new Error(`DECLARATION_NOT_FOUND ${name}`);
  let start = at;
  while (start > 0 && /^(\s*\*|\s*\/\*\*|\s*\*\/|\/\/)/u.test(lines[start - 1])) start--;
  // a doc block is attached only when it is a /** ... */ block or consecutive // lines directly above
  let end = at;
  if (/^(export )?function /u.test(lines[at])) {
    while (lines[end] !== '}') end++;
  } else {
    const single = /;\s*(\/\/.*)?$/u.test(lines[at]);
    if (!single) while (lines[end] !== '};') end++;
  }
  const text = lines.slice(start, end + 1).join('\n');
  return text.replace(/^export /mu, '');
}

export function buildCopy() {
  const parts = [];
  const sources = {};
  const exported = [];
  for (const source of SOURCES) {
    const bytes = readFileSync(source.file);
    sources[source.key] = sha256(bytes);
    const lines = bytes.toString('utf8').split('\n');
    parts.push(`// ---- ${source.key} (sha256 ${sources[source.key]}) ----`);
    for (const name of source.names) {
      parts.push(declaration(lines, name));
      exported.push(name);
    }
  }
  const header = [
    '// VERBATIM COPY of the pure functions of the SPK-07 spike at freeze B (harness sha256 ' + FREEZE_B_HARNESS_SHA256 + ').',
    '// Generated by test/fixtures/spike-pure/verify-copy.mjs --write; never edit by hand. Only `export ` was removed from each',
    '// top-level declaration and the module.exports line appended. Source file sha256s:',
    ...Object.entries(sources).map(([key, hash]) => `//   ${key} ${hash}`),
    "'use strict';",
  ];
  return `${header.join('\n')}\n\n${parts.join('\n\n')}\n\nmodule.exports = { ${exported.join(', ')} };\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = join(here, 'spike-pure.cjs');
  const built = buildCopy();
  if (process.argv.includes('--write')) {
    writeFileSync(target, built);
    console.log(`wrote ${target} sha256 ${sha256(built)}`);
  } else {
    const committed = readFileSync(target, 'utf8');
    if (committed !== built) {
      console.error('spike-pure.cjs differs from the spike at freeze B');
      process.exitCode = 1;
    } else console.log(`spike-pure.cjs matches the spike (sha256 ${sha256(committed)})`);
  }
}
